local config = {
  str_homestory_N21yongchi_90020101_1_dialog_content = "Wow, it's so hot...",
  str_homestory_N21yongchi_90020101_2_dialog_content = "Yeah, I feel like the weather has been a lot warmer lately.",
  str_homestory_N21yongchi_90020101_3_dialog_content = "Even plants in Cloud Gardens seem to have had enough of the sun.",
  str_homestory_N21yongchi_90020101_4_dialog_content = "I'm starting to miss Harbor City.",
  str_homestory_N21yongchi_90020101_5_dialog_content = "The breezes, the ocean in summer...",
  str_homestory_N21yongchi_90020101_6_dialog_content = "Oh, and being able to go swimming together...",
  str_homestory_N21yongchi_90020101_7_dialog_content = "Yeah, there's nowhere to swim in Cloud Gardens.",
  str_homestory_N21yongchi_90020101_8_dialog_content = "So, maybe we should make it somewhere?",
  str_homestory_N21yongchi_90020101_9_dialog_content = "I think people might like that.",
  str_homestory_N21yongchi_90020101_10_dialog_content = "Good idea!",
  str_homestory_N21yongchi_90020101_11_dialog_content = "We've already constructed lots of buildings. Why not have a Cloud Gardens Water Park?",
  str_homestory_N21yongchi_90020101_12_dialog_content = "Sounds like you've got a plan.",
  str_homestory_N21yongchi_90020101_13_dialog_content = "Not yet. But I definitely want a water park.",
  str_homestory_N21yongchi_90020101_14_dialog_content = "We'll need lots of water. And somewhere to put the water.",
  str_homestory_N21yongchi_90020101_15_dialog_content = "Let's start with digging out a swimming pool.",
  str_homestory_N21yongchi_90020101_16_dialog_content = "A pool big enough to hold lots of Aurorians will mean a lot of spadework.",
  str_homestory_N21yongchi_90020101_17_dialog_content = "There must be an Aurorian who's good at excavation and construction. Let me think...",
  str_homestory_N21yongchi_90020101_18_dialog_content = "That reminds me, Ciel's the person you need. She's got lots of experience with this kind of work.",
  str_homestory_N21yongchi_90020101_19_dialog_content = "Ciel? Got it!",
  str_homestory_N21yongchi_90020101_20_dialog_content = "I'll go and speak to her.",
  str_homestory_N21yongchi_90020102_1_dialog_content = "Ciel!",
  str_homestory_N21yongchi_90020102_2_dialog_content = "Ah! Oh, it's you, PlayerName.",
  str_homestory_N21yongchi_90020102_3_dialog_content = "Sorry, did I give you a fright?",
  str_homestory_N21yongchi_90020102_4_dialog_content = "No. I was just concentrating on making some adjustments to Styx.",
  str_homestory_N21yongchi_90020102_5_dialog_content = "Is something wrong with it?",
  str_homestory_N21yongchi_90020102_6_dialog_content = "I hope it's not malfunctioning.",
  str_homestory_N21yongchi_90020102_7_dialog_content = "No, nothing like that...",
  str_homestory_N21yongchi_90020102_8_dialog_content = "I had an idea for some ever-so-slightly radical adjustments.",
  str_homestory_N21yongchi_90020102_9_dialog_content = "PlayerName, you know I often help Officer Charon dig tunnels, don't you?",
  str_homestory_N21yongchi_90020102_10_dialog_content = "If these changes work, I can double Styx's excavation speed.",
  str_homestory_N21yongchi_90020102_11_dialog_content = "Wow, that's awesome!",
  str_homestory_N21yongchi_90020102_12_dialog_content = "The problem is, the duration performance has dropped by 90%...",
  str_homestory_N21yongchi_90020102_13_dialog_content = "That's... less awesome.",
  str_homestory_N21yongchi_90020102_14_dialog_content = "Yeah, so I need to keep working on it and see if I can come up with a fix.",
  str_homestory_N21yongchi_90020102_15_dialog_content = "I see.",
  str_homestory_N21yongchi_90020102_16_dialog_content = "Well, if there's anything I can do to help, just let me know.",
  str_homestory_N21yongchi_90020102_17_dialog_content = "Oh, really?",
  str_homestory_N21yongchi_90020102_18_dialog_content = "Actually... there is something you could do for me, PlayerName.",
  str_homestory_N21yongchi_90020102_19_dialog_content = "Sure. Name it!",
  str_homestory_N21yongchi_90020102_20_dialog_content = "Could you get me some ore?",
  str_homestory_N21yongchi_90020102_21_dialog_content = "I need it to test Styx.",
  str_homestory_N21yongchi_90020102_22_dialog_content = "Not a problem. Leave it with me.",
  str_homestory_N21yongchi_90020103_1_dialog_content = "Did you get the ore I need?",
  str_homestory_N21yongchi_90020103_2_dialog_content = "Sure did! ({1}/{2})",
  str_homestory_N21yongchi_90020103_3_dialog_content = "Thanks! I knew I could rely on you, PlayerName.",
  str_homestory_N21yongchi_90020103_4_dialog_content = "And you were so quick too.",
  str_homestory_N21yongchi_90020103_5_dialog_content = "Heheh. I think all the work I've been doing here in Cloud Gardens is making me stronger.",
  str_homestory_N21yongchi_90020103_6_dialog_content = "Jobs like this seem super-easy now.",
  str_homestory_N21yongchi_90020103_7_dialog_content = "And as it happens, I have a favor to ask you as well.",
  str_homestory_N21yongchi_90020103_8_dialog_content = "Yeah, I know. The swimming pool, right?",
  str_homestory_N21yongchi_90020103_9_dialog_content = "Huh? How did you know that, Ciel?",
  str_homestory_N21yongchi_90020103_10_dialog_content = "Miss Carleen came to see me while you were gathering the ore.",
  str_homestory_N21yongchi_90020103_11_dialog_content = "Leave it to me. All you need to do is mark out the area where you want to build the swimming pool.",
  str_homestory_N21yongchi_90020103_12_dialog_content = "I'll come and help when I've finished with Styx.",
  str_homestory_N21yongchi_90020103_13_dialog_content = "Okay. Thanks so much.",
  str_homestory_N21yongchi_90020103_14_dialog_content = "Not quite enough.",
  str_homestory_N21yongchi_90020103_15_dialog_content = "Well, I'm counting on you.",
  str_homestory_N21yongchi_90020104_1_dialog_content = "Huff, puff... This should tell Ciel where I want the swimming pool.",
  str_homestory_N21yongchi_90020104_2_dialog_content = "I'm not used to digging like that. It's tough work.",
  str_homestory_N21yongchi_90020104_3_dialog_content = "I can't even imagine having to dig out an entire swimming pool single-handed.",
  str_homestory_N21yongchi_90020104_4_dialog_content = "But this should be enough. Now all I have to do is wait for Ciel.",
  str_homestory_N21yongchi_90020104_5_dialog_content = "And... done!",
  str_homestory_N21yongchi_90020104_6_dialog_content = "Woah! That's unbelievable.",
  str_homestory_N21yongchi_90020104_7_dialog_content = "Ciel, you are awesome!",
  str_homestory_N21yongchi_90020104_8_dialog_content = "Well, it wasn't just me. I couldn't have done it without Styx.",
  str_homestory_N21yongchi_90020104_9_dialog_content = "And Miss Carleen gave me a lot of advice.",
  str_homestory_N21yongchi_90020104_10_dialog_content = "But it still doesn't look perfect.",
  str_homestory_N21yongchi_90020104_11_dialog_content = "You might need to do some polishing, PlayerName.",
  str_homestory_N21yongchi_90020104_12_dialog_content = "I think it's amazing already. And so much better than me and my spade could have done.",
  str_homestory_N21yongchi_90020104_13_dialog_content = "Leave the cleaning up to me, Ciel.",
  str_homestory_N21yongchi_90020105_1_dialog_content = "Yes! I've cleaned the swimming pool up, and now people can use it.",
  str_homestory_N21yongchi_90020105_2_dialog_content = "I'll go and tell Carleen.",
  str_homestory_N21yongchi_90020106_1_dialog_content = "Carleen!",
  str_homestory_N21yongchi_90020106_2_dialog_content = "PlayerName, you're back.",
  str_homestory_N21yongchi_90020106_3_dialog_content = "Did you get the ore for Ciel?",
  str_homestory_N21yongchi_90020106_4_dialog_content = "Yeah, I did. And the swimming pool has been built!",
  str_homestory_N21yongchi_90020106_5_dialog_content = "I didn't know you were going to speak to Ciel as well.",
  str_homestory_N21yongchi_90020106_6_dialog_content = "Yeah, I suddenly thought of a few ideas that might help.",
  str_homestory_N21yongchi_90020106_7_dialog_content = "So I went to see her and passed them on.",
  str_homestory_N21yongchi_90020106_8_dialog_content = "I didn't think the swimming pool would be so quick to build.",
  str_homestory_N21yongchi_90020106_9_dialog_content = "Well, it's still kind of basic. It's just the pool and nothing else.",
  str_homestory_N21yongchi_90020106_10_dialog_content = "I can help with that.",
  str_homestory_N21yongchi_90020106_11_dialog_content = "After all, you've been working so hard to welcome us all.",
  str_homestory_N21yongchi_90020106_12_dialog_content = "We can't rely on you to do everything.",
  str_homestory_N21yongchi_90020106_13_dialog_content = "It's only polite that we guests help you too.",
  str_homestory_N21yongchi_90020106_14_dialog_content = "Thank you, Carleen.",
  str_homestory_N21yongchi_90020106_15_dialog_content = "Though I've never thought of you as guests.",
  str_homestory_N21yongchi_90020106_16_dialog_content = "You're here in Cloud Gardens, and that makes you family.",
  str_homestory_N21yongchi_90020106_17_dialog_content = "And Cloud Gardens Water Park will be open to any Aurorian who wants to visit.",
  str_homestory_N21yongchi_90020106_18_dialog_content = "Sounds great!",
  str_homestory_N21yongchi_90020201_1_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020201_2_dialog_content = "Hi, Vice.",
  str_homestory_N21yongchi_90020201_3_dialog_content = "I passed by a beautiful swimming pool on the way here. Did you build it?",
  str_homestory_N21yongchi_90020201_4_dialog_content = "It wasn't here a few days ago, was it?",
  str_homestory_N21yongchi_90020201_5_dialog_content = "No. Carleen came up with the design, then Ciel did the construction work.",
  str_homestory_N21yongchi_90020201_6_dialog_content = "I think it's cool too!",
  str_homestory_N21yongchi_90020201_7_dialog_content = "Ah, I should have guessed Carleen contributed. There's a definite flavor of Lumopolis here.",
  str_homestory_N21yongchi_90020201_8_dialog_content = "And it's good to hear that Ciel is finding a use for all the tunnel-building skills she's accumulated.",
  str_homestory_N21yongchi_90020201_9_dialog_content = "Exactly! The pool would be nowhere near as big if it wasn't for her help.",
  str_homestory_N21yongchi_90020201_10_dialog_content = "But it's not going to be only a swimming pool. I'm planning a water park for everyone to swim and enjoy themselves in!",
  str_homestory_N21yongchi_90020201_11_dialog_content = "That sounds like you, PlayerName.",
  str_homestory_N21yongchi_90020201_12_dialog_content = "And you've got me all fired up now. How can I help?",
  str_homestory_N21yongchi_90020201_13_dialog_content = "(I've got a bad feeling about this.)",
  str_homestory_N21yongchi_90020201_14_dialog_content = "(When Vice says help, does she mean with... her cooking?)",
  str_homestory_N21yongchi_90020201_15_dialog_content = "I know!",
  str_homestory_N21yongchi_90020201_16_dialog_content = "Oh? W-What?",
  str_homestory_N21yongchi_90020201_17_dialog_content = "I remember learning to swim in Illumina.",
  str_homestory_N21yongchi_90020201_18_dialog_content = "The coach gave us some safety equipment to help.",
  str_homestory_N21yongchi_90020201_19_dialog_content = "Like inflatable balls and life preservers.",
  str_homestory_N21yongchi_90020201_20_dialog_content = "That way we could practice swimming more safely.",
  str_homestory_N21yongchi_90020201_21_dialog_content = "And Aurorians who hadn't swum before could get used to being in the water.",
  str_homestory_N21yongchi_90020201_22_dialog_content = "I see.",
  str_homestory_N21yongchi_90020201_23_dialog_content = "I guess it is a bit dangerous to just fill the pool with water...",
  str_homestory_N21yongchi_90020201_24_dialog_content = "Good thinking, Vice!",
  str_homestory_N21yongchi_90020201_25_dialog_content = "Heheh. Safety should always come first.",
  str_homestory_N21yongchi_90020201_26_dialog_content = "Let me think, where could we get that kind of gear...",
  str_homestory_N21yongchi_90020201_27_dialog_content = "I seem to remember the last time I went surfing...",
  str_homestory_N21yongchi_90020201_28_dialog_content = "I know! The circus will have some.",
  str_homestory_N21yongchi_90020201_29_dialog_content = "I should go and ask Rainbow.",
  str_homestory_N21yongchi_90020201_30_dialog_content = "Keep up the good work! I'll wait here for you.",
  str_homestory_N21yongchi_90020202_1_dialog_content = "It's PlayerName! Hello.",
  str_homestory_N21yongchi_90020202_2_dialog_content = "You seem to be in a good mood. What's happening?",
  str_homestory_N21yongchi_90020202_3_dialog_content = "Well, Cloud Gardens is my home. I'm just happy to be back here.",
  str_homestory_N21yongchi_90020202_4_dialog_content = "What about you, Rainbow? Are you settling in?",
  str_homestory_N21yongchi_90020202_5_dialog_content = "I think so, yes. After all, I had plenty of adventures on board the Emerald.",
  str_homestory_N21yongchi_90020202_6_dialog_content = "If anything, I suspect life on solid ground is a little... excessively stable.",
  str_homestory_N21yongchi_90020202_7_dialog_content = "So, PlayerName, why the sudden interest in me?",
  str_homestory_N21yongchi_90020202_8_dialog_content = "I saw you heading right for me from MILES away. Did you need something?",
  str_homestory_N21yongchi_90020202_9_dialog_content = "Haha, you've seen right through me.",
  str_homestory_N21yongchi_90020202_10_dialog_content = "It's like this: I've built a swimming pool in Cloud Gardens and I want to make it into a water park.",
  str_homestory_N21yongchi_90020202_11_dialog_content = "But there are lots of Aurorians here who can't swim.",
  str_homestory_N21yongchi_90020202_12_dialog_content = "So I wanted to ask if there were any spare swim rings onboard the Emerald.",
  str_homestory_N21yongchi_90020202_13_dialog_content = "Ah. Well, you've come to the right person. I'm in charge of the safety equipment stores.",
  str_homestory_N21yongchi_90020202_14_dialog_content = "Bet you didn't expect that.",
  str_homestory_N21yongchi_90020202_15_dialog_content = "Haha! Well, given how many jobs you already have, Rainbow, I guess I shouldn't be surprised to find you've got yet one more.",
  str_homestory_N21yongchi_90020202_16_dialog_content = "So, could you lend me some? Or I could buy them from you?",
  str_homestory_N21yongchi_90020202_17_dialog_content = "Well... I don't think I can. They're not mine, they belong to the Emerald. I just look after them.",
  str_homestory_N21yongchi_90020202_18_dialog_content = "Although if you could do me a small favor, PlayerName...",
  str_homestory_N21yongchi_90020202_19_dialog_content = "Anything. Just name it.",
  str_homestory_N21yongchi_90020202_20_dialog_content = "Heheh, you sure are easy to deal with, PlayerName.",
  str_homestory_N21yongchi_90020202_21_dialog_content = "Our ringmaster, Jeno, loves to keep fish. He's fascinated by all the different species here in Cloud Gardens.",
  str_homestory_N21yongchi_90020202_22_dialog_content = "Maybe you could catch a few for him? If you do that, I'm sure I can talk him into giving you a few swim rings.",
  str_homestory_N21yongchi_90020202_23_dialog_content = "Got it. And I'm a champion fisherman.",
  str_homestory_N21yongchi_90020202_24_dialog_content = "Wait right there. I'll be back in two shakes of a fish's tail.",
  str_homestory_N21yongchi_90020203_1_dialog_content = "Did you get the fish?",
  str_homestory_N21yongchi_90020203_2_dialog_content = "Sure did! ({1}/{2})",
  str_homestory_N21yongchi_90020203_3_dialog_content = "Woah, you caught so many. Let me have a look.",
  str_homestory_N21yongchi_90020203_4_dialog_content = "Hmm, this one is the cutest. It looks like the type that Jeno would like.",
  str_homestory_N21yongchi_90020203_5_dialog_content = "I've left the swim rings you wanted by your pool.",
  str_homestory_N21yongchi_90020203_6_dialog_content = "And he's also given you a changing room we used to use during competitions. It's kind of basic.",
  str_homestory_N21yongchi_90020203_7_dialog_content = "But it'll give visitors somewhere to get changed and take showers.",
  str_homestory_N21yongchi_90020203_8_dialog_content = "Thank you so much, Rainbow!",
  str_homestory_N21yongchi_90020203_9_dialog_content = "Don't mention it, PlayerName. Although if you're not busy, maybe you could fetch some water to keep these fish in?",
  str_homestory_N21yongchi_90020203_10_dialog_content = "I don't think they've got enough space right now. I want to put them into a bigger container before I take them to Jeno.",
  str_homestory_N21yongchi_90020203_11_dialog_content = "No problem. I'll be right back!",
  str_homestory_N21yongchi_90020203_12_dialog_content = "I'm working on it!",
  str_homestory_N21yongchi_90020203_13_dialog_content = "Do your best!",
  str_homestory_N21yongchi_90020204_1_dialog_content = "Got it?",
  str_homestory_N21yongchi_90020204_2_dialog_content = "I did!",
  str_homestory_N21yongchi_90020204_3_dialog_content = "That was fast. Okay, thanks.",
  str_homestory_N21yongchi_90020204_4_dialog_content = "And I'll take these fish too.",
  str_homestory_N21yongchi_90020204_5_dialog_content = "Sure!",
  str_homestory_N21yongchi_90020204_6_dialog_content = "On my way.",
  str_homestory_N21yongchi_90020204_7_dialog_content = "A little bit of water will do it, thank you.",
  str_homestory_N21yongchi_90020205_1_dialog_content = "Okay, that should work.",
  str_homestory_N21yongchi_90020205_2_dialog_content = "And I'll put the inflatable balls nearby.",
  str_homestory_N21yongchi_90020301_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020301_2_dialog_content = "Hey, Ringmaster Jeno!",
  str_homestory_N21yongchi_90020301_3_dialog_content = "I was just thinking about you! I want to ask you about the new water park: how do you think we can make sure it's a success?",
  str_homestory_N21yongchi_90020301_4_dialog_content = "Water park?",
  str_homestory_N21yongchi_90020301_5_dialog_content = "Oh yes, Ciel mentioned it.",
  str_homestory_N21yongchi_90020301_6_dialog_content = "Honestly, I think it already looks great.",
  str_homestory_N21yongchi_90020301_7_dialog_content = "But...",
  str_homestory_N21yongchi_90020301_8_dialog_content = "But?",
  str_homestory_N21yongchi_90020301_9_dialog_content = "It is lacking something. A very important something.",
  str_homestory_N21yongchi_90020301_10_dialog_content = "Think back. What is your clearest summer memory?",
  str_homestory_N21yongchi_90020301_11_option_content = "Mosquito bites.",
  str_homestory_N21yongchi_90020301_12_dialog_content = "Not that. I mean a good memory.",
  str_homestory_N21yongchi_90020301_13_option_content = "Ah. A cold drink?",
  str_homestory_N21yongchi_90020301_14_dialog_content = "Close, but no.",
  str_homestory_N21yongchi_90020301_15_dialog_content = "Okay, I'll just tell you.",
  str_homestory_N21yongchi_90020301_16_dialog_content = "What your water park needs is... ice cream.",
  str_homestory_N21yongchi_90020301_17_dialog_content = "Milk and sugar are perfectly combined at sub-zero temperatures.",
  str_homestory_N21yongchi_90020301_18_dialog_content = "Hitting your tongue like frozen fireworks in the scorching summer heat.",
  str_homestory_N21yongchi_90020301_19_dialog_content = "I'm not keen on sugary foods. They make people grow weight. But I can't deny that ice cream also makes people happy.",
  str_homestory_N21yongchi_90020301_20_dialog_content = "Got it!",
  str_homestory_N21yongchi_90020301_21_dialog_content = "Ice cream, hmm... I'll speak to Vice, she made shaved ice last year!",
  str_homestory_N21yongchi_90020301_22_dialog_content = "Thank you, Jeno!",
  str_homestory_N21yongchi_90020301_23_dialog_content = "Leaving so soon?",
  str_homestory_N21yongchi_90020301_24_dialog_content = "What a rush.",
  str_homestory_N21yongchi_90020302_1_dialog_content = "Vice!",
  str_homestory_N21yongchi_90020302_2_dialog_content = "Huh? What's up, PlayerName? You're out of breath.",
  str_homestory_N21yongchi_90020302_3_dialog_content = "I know how we can attract more people to Cloud Gardens Water Park!",
  str_homestory_N21yongchi_90020302_4_dialog_content = "Oh? Well, don't keep me in suspense.",
  str_homestory_N21yongchi_90020302_5_dialog_content = "Remember last year when we made shaved ice?",
  str_homestory_N21yongchi_90020302_6_dialog_content = "What, shaved ices again?",
  str_homestory_N21yongchi_90020302_7_dialog_content = "To be honest, I kind of lost interest in shaved ices.",
  str_homestory_N21yongchi_90020302_8_dialog_content = "Because my talks with Kleken about a shaved ice franchise fell through, remember?",
  str_homestory_N21yongchi_90020302_9_dialog_content = "It's not shaved ices!",
  str_homestory_N21yongchi_90020302_10_dialog_content = "This time we're going to make ice cream!",
  str_homestory_N21yongchi_90020302_11_dialog_content = "I see...",
  str_homestory_N21yongchi_90020302_12_dialog_content = "Shaved ices are mostly water, so the flavor is always a little dull.",
  str_homestory_N21yongchi_90020302_13_dialog_content = "But if we add in milk and fruit, or even meat... We can come up with millions of different types!",
  str_homestory_N21yongchi_90020302_14_dialog_content = "Er... meat?",
  str_homestory_N21yongchi_90020302_15_dialog_content = "You're right, I should never have limited myself to shaved ice. And I can add a whole new dimension to so many different foods by freezing them!",
  str_homestory_N21yongchi_90020302_16_dialog_content = "Huh?",
  str_homestory_N21yongchi_90020302_17_dialog_content = "Thanks! You're a true inspiration.",
  str_homestory_N21yongchi_90020302_18_dialog_content = "I'll come up with some samplings. PlayerName, find a few people to taste them.",
  str_homestory_N21yongchi_90020302_19_dialog_content = "Or maybe you'd prefer to taste my inventions yourself, PlayerName.",
  str_homestory_N21yongchi_90020302_20_dialog_content = "I-I'll be in charge of recruiting testers. You get to work!",
  str_homestory_N21yongchi_90020303_1_dialog_content = "Hmm. Who should I ask?",
  str_homestory_N21yongchi_90020303_2_dialog_content = "Why, if it isn't PlayerName!",
  str_homestory_N21yongchi_90020303_3_dialog_content = "What are you so deep in thought about?",
  str_homestory_N21yongchi_90020303_4_dialog_content = "Oh! Brock.",
  str_homestory_N21yongchi_90020303_5_dialog_content = "(I recall Brock could even down sandworm protein drinks.)",
  str_homestory_N21yongchi_90020303_6_dialog_content = "(Brock, my friend, I apologize for what I'm about to inflict on you.)",
  str_homestory_N21yongchi_90020303_7_dialog_content = "Hey, how come you're drenched in sweat?",
  str_homestory_N21yongchi_90020303_8_dialog_content = "This? Well, I just did 100 push-ups, 100 sit-ups, and 100 squats.",
  str_homestory_N21yongchi_90020303_9_dialog_content = "That got me warmed up. Then I ran for 10 kilometers.",
  str_homestory_N21yongchi_90020303_10_dialog_content = "It's the favorite routine for Rediesel Wrench members on their days off.",
  str_homestory_N21yongchi_90020303_11_dialog_content = "That's a day off? Anyway, you must be hot after all that exercise.",
  str_homestory_N21yongchi_90020303_12_dialog_content = "How would you like to try a new flavor of ice cream?",
  str_homestory_N21yongchi_90020303_13_dialog_content = "It'll help replenish your energy and make you even stronger.",
  str_homestory_N21yongchi_90020303_14_dialog_content = "Sounds smart!",
  str_homestory_N21yongchi_90020303_15_dialog_content = "I knew you supported me more other than Sinsa!",
  str_homestory_N21yongchi_90020303_16_dialog_content = "Come on then. Where's this delicious ice cream?",
  str_homestory_N21yongchi_90020303_17_dialog_content = "Here, try it!",
  str_homestory_N21yongchi_90020303_18_dialog_content = "Lick lick.",
  str_homestory_N21yongchi_90020303_19_dialog_content = "Slurp slurp.",
  str_homestory_N21yongchi_90020303_20_dialog_content = "<color=#e8d9bb>Kaboom!</color>",
  str_homestory_N21yongchi_90020303_21_dialog_content = "Woah!!",
  str_homestory_N21yongchi_90020303_22_dialog_content = "What's the story with this ice cream?",
  str_homestory_N21yongchi_90020303_23_dialog_content = "When I swallowed it, I felt like someone had punched me in the gut.",
  str_homestory_N21yongchi_90020303_24_dialog_content = "That's a sneaky trick. Even sneakier than Sinsa.",
  str_homestory_N21yongchi_90020303_25_dialog_content = "W-wait a minute. Let me think of an... I mean, explain!",
  str_homestory_N21yongchi_90020303_26_dialog_content = "I know! Maybe... it's a way to train to take a punch?",
  str_homestory_N21yongchi_90020303_27_dialog_content = "I mean, you'll need more than muscles to beat Sinsa, right?",
  str_homestory_N21yongchi_90020303_28_dialog_content = "You need to be able to keep fighting, even after taking a hit, if you want to have the last laugh.",
  str_homestory_N21yongchi_90020303_29_dialog_content = "...",
  str_homestory_N21yongchi_90020303_30_dialog_content = "...",
  str_homestory_N21yongchi_90020303_31_dialog_content = "You're a genius!",
  str_homestory_N21yongchi_90020303_32_dialog_content = "Is there any more? Can I have some?",
  str_homestory_N21yongchi_90020304_1_dialog_content = "Ringmaster Jeno.",
  str_homestory_N21yongchi_90020304_2_dialog_content = "Oh, hello PlayerName.",
  str_homestory_N21yongchi_90020304_3_dialog_content = "Have you already made some ice cream? I should have known you would.",
  str_homestory_N21yongchi_90020304_4_dialog_content = "Well, this is just a sample.",
  str_homestory_N21yongchi_90020304_5_dialog_content = "But I heard you're a true gourmet, so...",
  str_homestory_N21yongchi_90020304_6_dialog_content = "I know. You want me to try it, don't you?",
  str_homestory_N21yongchi_90020304_7_dialog_content = "I'm not keen on sugary foods. But it was my idea, after all.",
  str_homestory_N21yongchi_90020304_8_dialog_content = "Let me have a taste.",
  str_homestory_N21yongchi_90020304_9_dialog_content = "Slurp slurp.",
  str_homestory_N21yongchi_90020304_10_dialog_content = "Wh-what is this?",
  str_homestory_N21yongchi_90020304_11_dialog_content = "This isn't frozen fireworks. This is a clap of thunder inside my head.",
  str_homestory_N21yongchi_90020304_12_dialog_content = "It's so... taboo. A forbidden flavor.",
  str_homestory_N21yongchi_90020304_13_dialog_content = "Yet so enchanting.",
  str_homestory_N21yongchi_90020304_14_dialog_content = "...",
  str_homestory_N21yongchi_90020304_15_dialog_content = "Jeno, are you okay?",
  str_homestory_N21yongchi_90020304_16_dialog_content = "Take this, PlayerName.",
  str_homestory_N21yongchi_90020304_17_dialog_content = "Wh-what is it?",
  str_homestory_N21yongchi_90020304_18_dialog_content = "An ice cream machine.",
  str_homestory_N21yongchi_90020304_19_dialog_content = "My predecessor once said to me—",
  str_homestory_N21yongchi_90020304_20_dialog_content = "If you ever find someone whose ice cream makes your tastebuds go twang, bestow this gift upon them.",
  str_homestory_N21yongchi_90020304_21_dialog_content = "This ice cream machine has been with the Emerald for many years. I hope it serves you well.",
  str_homestory_N21yongchi_90020304_22_dialog_content = "And that you use it to bring that flavor to many more mouths.",
  str_homestory_N21yongchi_90020304_23_dialog_content = "Boo-hoo... I'm touched.",
  str_homestory_N21yongchi_90020304_24_dialog_content = "Thank you, Jeno!",
  str_homestory_N21yongchi_90020305_1_dialog_content = "Vice, I'm back!",
  str_homestory_N21yongchi_90020305_2_dialog_content = "Great, PlayerName.",
  str_homestory_N21yongchi_90020305_3_dialog_content = "What did everyone think of my ice cream?",
  str_homestory_N21yongchi_90020305_4_dialog_content = "Well! Brock rated it very highly.",
  str_homestory_N21yongchi_90020305_5_dialog_content = "He said it would be of great help in his physical training routine.",
  str_homestory_N21yongchi_90020305_6_dialog_content = "Hmm. I didn't realize he was a man of such fine taste.",
  str_homestory_N21yongchi_90020305_7_dialog_content = "I actually added a can of a new nutritious canned meat from Illumina to the mix.",
  str_homestory_N21yongchi_90020305_8_dialog_content = "So why do you have to add meat to ice cream...",
  str_homestory_N21yongchi_90020305_9_dialog_content = "Oh. Any other reviews?",
  str_homestory_N21yongchi_90020305_10_dialog_content = "Yes! Jeno said it was delicious.",
  str_homestory_N21yongchi_90020305_11_dialog_content = "And he even gave us this ice cream machine.",
  str_homestory_N21yongchi_90020305_12_dialog_content = "Awesome! That means everyone is sure to enjoy my new ice cream.",
  str_homestory_N21yongchi_90020305_13_dialog_content = "And with this machine to help, it'll be even easier to make them.",
  str_homestory_N21yongchi_90020305_14_dialog_content = "We'll be as efficient as a meat-canning factory.",
  str_homestory_N21yongchi_90020305_15_dialog_content = "Weird comparison, but okay...",
  str_homestory_N21yongchi_90020305_16_dialog_content = "Should I try them too, before we offer them to the public...",
  str_homestory_N21yongchi_90020306_1_dialog_content = "Okay, everything's cleared up.",
  str_homestory_N21yongchi_90020306_2_dialog_content = "Now everyone can enjoy Vice's ice cream.",
  str_homestory_N21yongchi_90020306_3_dialog_content = "Hmm. Should I try one, or not?",
  str_homestory_N21yongchi_90020306_4_dialog_content = "Haha. Forget it, maybe I'll have one later.",
  str_homestory_N21yongchi_90020401_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020401_2_dialog_content = "Chief Vivian!",
  str_homestory_N21yongchi_90020401_3_dialog_content = "You look worried about something. Can I be of any help?",
  str_homestory_N21yongchi_90020401_4_dialog_content = "Wow, how could you tell?",
  str_homestory_N21yongchi_90020401_5_dialog_content = "Impressive Caelestite indeed, able to sense the slightest emotion from others.",
  str_homestory_N21yongchi_90020401_6_dialog_content = "Haha. Maybe the way your brows are all scrunched up helped.",
  str_homestory_N21yongchi_90020401_7_dialog_content = "Let me guess. Officer Philyshy is missing again?",
  str_homestory_N21yongchi_90020401_8_dialog_content = "Yes, and she's overdue with an important intel report.",
  str_homestory_N21yongchi_90020401_9_dialog_content = "Nobody can find her anywhere.",
  str_homestory_N21yongchi_90020401_10_dialog_content = "She's a real headache.",
  str_homestory_N21yongchi_90020401_11_dialog_content = "(Philyshy has been sneaking off for naps lately... maybe she's near the water?)",
  str_homestory_N21yongchi_90020401_12_dialog_content = "I think I've got an idea where she might be.",
  str_homestory_N21yongchi_90020401_13_dialog_content = "Seriously? It'd be a huge help if you could find her.",
  str_homestory_N21yongchi_90020401_14_dialog_content = "Wait while I go and look for her.",
  str_homestory_N21yongchi_90020401_15_dialog_content = "Oh, thank you, PlayerName!",
  str_homestory_N21yongchi_90020402_1_dialog_content = "Hey! Dove!",
  str_homestory_N21yongchi_90020402_2_dialog_content = "Waaaaaaaaaaaaah—",
  str_homestory_N21yongchi_90020402_3_dialog_content = "Who is it? Who's making such a racket?",
  str_homestory_N21yongchi_90020402_4_dialog_content = "PlayerName, it's you?",
  str_homestory_N21yongchi_90020402_5_dialog_content = "Why are you slacking off in here, Dove?",
  str_homestory_N21yongchi_90020402_6_dialog_content = "S-Slacking off? I'm not!",
  str_homestory_N21yongchi_90020402_7_dialog_content = "I just wanted to have a nap because I've been working so hard. And then you gave me such a fright.",
  str_homestory_N21yongchi_90020402_8_dialog_content = "Oh? So you've finished delivering all your mails?",
  str_homestory_N21yongchi_90020402_9_dialog_content = "Oh, the mails... I'll get right onto that, just as soon as I've caught up on my sleep.",
  str_homestory_N21yongchi_90020402_10_dialog_content = "And what are you up to anyway? You can't disturb my sleep like that without explaining yourself.",
  str_homestory_N21yongchi_90020402_11_dialog_content = "Oh yes. Sorry about that. I was actually looking for Philyshy.",
  str_homestory_N21yongchi_90020402_12_dialog_content = "Here, have a voucher for some ice cream as an apology. If you're near the swimming pool, you can try one of Vice's new flavors.",
  str_homestory_N21yongchi_90020402_13_dialog_content = "Okay. I guess I'll forgive you then. But I don't know where Philyshy is.",
  str_homestory_N21yongchi_90020402_14_dialog_content = "Anyway, I'd be more likely to visit if the swimming pool had somewhere to sleep. That's more important than ice cream, I think.",
  str_homestory_N21yongchi_90020402_15_dialog_content = "Maybe a lounge chair under a parasol?",
  str_homestory_N21yongchi_90020402_16_dialog_content = "Just the essentials so us hard-workers can relax properly.",
  str_homestory_N21yongchi_90020402_17_dialog_content = "You're right. Let me think.",
  str_homestory_N21yongchi_90020402_18_dialog_content = "Somewhere to relax... to relax... Philyshy... Got it!",
  str_homestory_N21yongchi_90020402_19_dialog_content = "Don't forget to visit the water park, Dove!",
  str_homestory_N21yongchi_90020402_20_dialog_content = "Huh? Okay, sure.",
  str_homestory_N21yongchi_90020403_1_dialog_content = "PlayerName, what are you doing?",
  str_homestory_N21yongchi_90020403_2_dialog_content = "I'm about to make some lounge chairs out of wood.",
  str_homestory_N21yongchi_90020403_3_dialog_content = "What do you think? They're good, right?",
  str_homestory_N21yongchi_90020403_4_dialog_content = "Yeah. I knew about your battlefield command skills, but... It looks like you've still got some surprises hidden away.",
  str_homestory_N21yongchi_90020403_5_dialog_content = "Now anyone coming to visit the water park can take a rest anytime they want to.",
  str_homestory_N21yongchi_90020403_6_dialog_content = "This water park is getting more and more comfortable.",
  str_homestory_N21yongchi_90020403_7_dialog_content = "Yeah. Now people can have a place to lie down if they get tired from swimming or if they want to enjoy an ice cream.",
  str_homestory_N21yongchi_90020403_8_dialog_content = "And that's not the best bit. These lounge chairs have a secret power.",
  str_homestory_N21yongchi_90020403_9_dialog_content = "A secret power?",
  str_homestory_N21yongchi_90020403_10_dialog_content = "Once I've made them and set them up, you'll be able to see the results!",
  str_homestory_N21yongchi_90020404_1_dialog_content = "Okay, this is all sparkling clean now.",
  str_homestory_N21yongchi_90020404_2_dialog_content = "Now all I need to do is put the lounge chairs out and wait for the magic to happen.",
  str_homestory_N21yongchi_90020404_3_dialog_content = "And I should take the chance to get Chief Vivian over.",
  str_homestory_N21yongchi_90020405_1_dialog_content = "Zzzz... Zzzz... meow.",
  str_homestory_N21yongchi_90020405_2_dialog_content = "It worked! Following the footprints led to Philyshy!",
  str_homestory_N21yongchi_90020405_3_dialog_content = "How come you look asleep even when you're standing up?",
  str_homestory_N21yongchi_90020405_4_dialog_content = "Huh? Quieten down, PlayerName. I've only just woken up.",
  str_homestory_N21yongchi_90020405_5_dialog_content = "Well, you'd better stop sleeping.",
  str_homestory_N21yongchi_90020405_6_dialog_content = "Someone's looking for you.",
  str_homestory_N21yongchi_90020405_7_dialog_content = "W-Who meow? I've only been awake for five minutes. I need to...",
  str_homestory_N21yongchi_90020405_8_dialog_content = "Phi—ly—shy—!",
  str_homestory_N21yongchi_90020405_9_dialog_content = "Meow?!",
  str_homestory_N21yongchi_90020405_10_dialog_content = "O-Officer Vivian?",
  str_homestory_N21yongchi_90020405_11_dialog_content = "W-Why are you here meow?",
  str_homestory_N21yongchi_90020405_12_dialog_content = "Why haven't you delivered that intel I asked you for?",
  str_homestory_N21yongchi_90020405_13_dialog_content = "And why can't I find you anywhere? You wouldn't be avoiding me, would you?",
  str_homestory_N21yongchi_90020405_14_dialog_content = "A-Avoiding you? As if I would...",
  str_homestory_N21yongchi_90020405_15_dialog_content = "L-Let me explain meow...",
  str_homestory_N21yongchi_90020405_16_dialog_content = "Okay, you can do that on our way back.",
  str_homestory_N21yongchi_90020405_17_dialog_content = "And don't worry if you can't explain fully now. I've got lots of time this evening to listen to a full and comprehensive explanation.",
  str_homestory_N21yongchi_90020405_18_dialog_content = "Oh meow. You sure look terrifying, Chief Vivian.",
  str_homestory_N21yongchi_90020405_19_dialog_content = "This is all because of PlayerName and that lovely lounge chair.",
  str_homestory_N21yongchi_90020405_20_dialog_content = "I'll come with you as ordered meow.",
  str_homestory_N21yongchi_90020405_21_dialog_content = "PlayerName, is that the secret power you mentioned?",
  str_homestory_N21yongchi_90020405_22_dialog_content = "A Philyshy trap... very clever.",
  str_homestory_N21yongchi_90020405_23_dialog_content = "Sure did. I figured she was probably deliberately hiding from everyone, but she wouldn't be able to resist a comfortable resting place.",
  str_homestory_N21yongchi_90020405_24_dialog_content = "And sure enough, she turned up.",
  str_homestory_N21yongchi_90020405_25_dialog_content = "Now I'm sure the lounge chairs are comfortable.",
  str_homestory_N21yongchi_90020501_1_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020501_2_dialog_content = "What are you so worried about?",
  str_homestory_N21yongchi_90020501_3_dialog_content = "The water park looks gorgeous. Is something else bothering you?",
  str_homestory_N21yongchi_90020501_4_dialog_content = "Well... I want to make it even better, so even more people can enjoy it.",
  str_homestory_N21yongchi_90020501_5_dialog_content = "I've tried adding some plants to the water to make the air fresher.",
  str_homestory_N21yongchi_90020501_6_dialog_content = "And also opening up some more snack stalls.",
  str_homestory_N21yongchi_90020501_7_dialog_content = "I've even thought about having blind bags to sell as Jomu does.",
  str_homestory_N21yongchi_90020501_8_dialog_content = "Oh, blind bags... I wouldn't do that.",
  str_homestory_N21yongchi_90020501_9_dialog_content = "And is there anything else you'd like to improve?",
  str_homestory_N21yongchi_90020501_10_dialog_content = "I'm not sure. I just keep thinking there's something missing when I compare it to my memories of the Emerald.",
  str_homestory_N21yongchi_90020501_11_dialog_content = "Maybe it's not so... lively?",
  str_homestory_N21yongchi_90020501_12_dialog_content = "It seems to feel a little cheerless.",
  str_homestory_N21yongchi_90020501_13_dialog_content = "Maybe you need someone like Rainbow, a host to get everyone fired up.",
  str_homestory_N21yongchi_90020501_14_dialog_content = "People will liven up if we've got someone who can create a happy atmosphere.",
  str_homestory_N21yongchi_90020501_15_dialog_content = "That makes sense.",
  str_homestory_N21yongchi_90020501_16_dialog_content = "But I can't hang around by the pool doing that all the time.",
  str_homestory_N21yongchi_90020501_17_dialog_content = "Let me think. How to create an atmosphere?",
  str_homestory_N21yongchi_90020501_18_dialog_content = "How about some music? Lots of different places use music to create the appropriate atmosphere.",
  str_homestory_N21yongchi_90020501_19_dialog_content = "In Umbraton, some stores play classical music to help the customers feel relaxed and at home.",
  str_homestory_N21yongchi_90020501_20_dialog_content = "And that means they spend more.",
  str_homestory_N21yongchi_90020501_21_dialog_content = "But where am I going to find the equipment?",
  str_homestory_N21yongchi_90020501_22_dialog_content = "I think I remember music on the Emerald.",
  str_homestory_N21yongchi_90020501_23_dialog_content = "Yeah, you're right. They played it between the competitions.",
  str_homestory_N21yongchi_90020501_24_dialog_content = "Then I should go and ask Rainbow again.",
  str_homestory_N21yongchi_90020502_1_dialog_content = "Rainbow!",
  str_homestory_N21yongchi_90020502_2_dialog_content = "PlayerName, you're all sweaty again. What's the rush?",
  str_homestory_N21yongchi_90020502_3_dialog_content = "I told you to slow down. I'm not going anywhere anyway.",
  str_homestory_N21yongchi_90020502_4_dialog_content = "Did everyone like those gifts I gave you?",
  str_homestory_N21yongchi_90020502_5_dialog_content = "Yes! Thank you, Rainbow. And Ringmaster Jeno too.",
  str_homestory_N21yongchi_90020502_6_dialog_content = "A lot of Aurorians who can't swim are able to enjoy the water park, thanks to you both.",
  str_homestory_N21yongchi_90020502_7_dialog_content = "Heheh. Seems like Aurorians have a natural affinity for water.",
  str_homestory_N21yongchi_90020502_8_dialog_content = "No one can resist a floatie in the water.",
  str_homestory_N21yongchi_90020502_9_dialog_content = "Well, as long as you guys like it. So, what is it this time?",
  str_homestory_N21yongchi_90020502_10_dialog_content = "Well... I'd like to equip the water park with some sort of place to blast music.",
  str_homestory_N21yongchi_90020502_11_dialog_content = "Oh. That won't be cheap.",
  str_homestory_N21yongchi_90020502_12_dialog_content = "And it's not something I can decide for myself. You should speak to Jeno.",
  str_homestory_N21yongchi_90020502_13_dialog_content = "He's not just a keen painter, you know. He also has lots of opinions about music.",
  str_homestory_N21yongchi_90020502_14_dialog_content = "He's truly a seafaring legend.",
  str_homestory_N21yongchi_90020502_15_dialog_content = "Haha. Thanks, Rainbow.",
  str_homestory_N21yongchi_90020502_16_dialog_content = "I'll go and speak to him.",
  str_homestory_N21yongchi_90020503_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020503_2_dialog_content = "How come I get a funny feeling in my stomach when I see you?",
  str_homestory_N21yongchi_90020503_3_dialog_content = "Maybe... it's something to do with that ice cream?",
  str_homestory_N21yongchi_90020503_4_dialog_content = "I think so. I can't recall the flavor, but the memory of that experience is still very clear.",
  str_homestory_N21yongchi_90020503_5_dialog_content = "Although it seems to be my stomach that remembers it, not me.",
  str_homestory_N21yongchi_90020503_6_dialog_content = "It's bizarre. Very weird indeed.",
  str_homestory_N21yongchi_90020503_7_dialog_content = "Well, if you want some more, you're always welcome at Cloud Gardens Water Park.",
  str_homestory_N21yongchi_90020503_8_dialog_content = "Thank you. But I try to avoid sugary foods.",
  str_homestory_N21yongchi_90020503_9_dialog_content = "If I got fat, I wouldn't have the flexibility I need for my magic shows.",
  str_homestory_N21yongchi_90020503_10_dialog_content = "Oh, but was it sweet? Why is it that my brain goes all fuzzy whenever I try to remember that flavor?",
  str_homestory_N21yongchi_90020503_11_dialog_content = "Okay, sure, er, let's discuss the ice cream another time.",
  str_homestory_N21yongchi_90020503_12_dialog_content = "I need a favor, Jeno. Where can I buy some music gear?",
  str_homestory_N21yongchi_90020503_13_dialog_content = "Oh, I see. You want to play music at the water park and create a better atmosphere, right?",
  str_homestory_N21yongchi_90020503_14_dialog_content = "I should have known you'd guess right, Jeno.",
  str_homestory_N21yongchi_90020503_15_dialog_content = "Sure. And it's a funny coincidence...",
  str_homestory_N21yongchi_90020503_16_dialog_content = "I happen to have some old equipment I could sell you.",
  str_homestory_N21yongchi_90020503_17_dialog_content = "Oh, thank—",
  str_homestory_N21yongchi_90020503_18_dialog_content = "For 50 million Nightium.",
  str_homestory_N21yongchi_90020503_19_dialog_content = "What!?",
  str_homestory_N21yongchi_90020503_20_dialog_content = "Th-that's too much.",
  str_homestory_N21yongchi_90020503_21_dialog_content = "Not at all. We're talking about a very rare collectible DJ deck. I paid twice that for it when I acquired it.",
  str_homestory_N21yongchi_90020503_22_dialog_content = "But as we are friends, it wouldn't feel right to sell you the legendary Suffering Knight DJ Deck.",
  str_homestory_N21yongchi_90020503_23_dialog_content = "And it's not something I'd want to put a monetary value on.",
  str_homestory_N21yongchi_90020503_24_dialog_content = "But I need you to prove you are worthy of it.",
  str_homestory_N21yongchi_90020503_25_dialog_content = "I have spent countless happy days with it. You have to show me that you will look after it.",
  str_homestory_N21yongchi_90020503_26_dialog_content = "(Oh, I get it. Jeno is actually a very nostalgic person.)",
  str_homestory_N21yongchi_90020503_27_dialog_content = "So, show me how much you want it!",
  str_homestory_N21yongchi_90020503_28_dialog_content = "By bringing me the rarest and most valuable fish to be found in these parts.",
  str_homestory_N21yongchi_90020503_29_dialog_content = "I-I will!",
  str_homestory_N21yongchi_90020504_1_dialog_content = "Did you get them?",
  str_homestory_N21yongchi_90020504_2_dialog_content = "I did! ({1}/{2})",
  str_homestory_N21yongchi_90020504_3_dialog_content = "I didn't think you would be able to.",
  str_homestory_N21yongchi_90020504_4_dialog_content = "But keep them. I never really wanted them.",
  str_homestory_N21yongchi_90020504_5_dialog_content = "I just wanted to see how determined you were. How hard you would work.",
  str_homestory_N21yongchi_90020504_6_dialog_content = "So, did I pass the test?",
  str_homestory_N21yongchi_90020504_7_dialog_content = "Of course. The DJ deck is yours.",
  str_homestory_N21yongchi_90020504_8_dialog_content = "And I am sure its beautiful tones will bring you a greater understanding of the truth of this world.",
  str_homestory_N21yongchi_90020504_9_dialog_content = "Please, take good care of it.",
  str_homestory_N21yongchi_90020504_10_dialog_content = "Of course, Jeno! I will.",
  str_homestory_N21yongchi_90020504_11_dialog_content = "Almost there!",
  str_homestory_N21yongchi_90020504_12_dialog_content = "Good. Prove it to me.",
  str_homestory_N21yongchi_90020505_1_dialog_content = "Yeah! Now we've cleared a space, and we can set up the Suffering Knight DJ Deck.",
  str_homestory_N21yongchi_90020505_2_dialog_content = "Although... how does it actually work?",
  str_homestory_N21yongchi_90020601_1_dialog_content = "PlayerName.",
  str_homestory_N21yongchi_90020601_2_dialog_content = "...",
  str_homestory_N21yongchi_90020601_3_dialog_content = "PlayerName!",
  str_homestory_N21yongchi_90020601_4_dialog_content = "...",
  str_homestory_N21yongchi_90020601_5_dialog_content = "Lousy Caelestite!",
  str_homestory_N21yongchi_90020601_6_dialog_content = "Huh? What?",
  str_homestory_N21yongchi_90020601_7_dialog_content = "Fia, it's you!",
  str_homestory_N21yongchi_90020601_8_dialog_content = "You were miles away. What's on your mind?",
  str_homestory_N21yongchi_90020601_9_dialog_content = "You kept ignoring me. An extrozoologist like me deserves more respect.",
  str_homestory_N21yongchi_90020601_10_dialog_content = "Sorry, sorry!",
  str_homestory_N21yongchi_90020601_11_dialog_content = "I was daydreaming, imagining lots of people enjoying the water park.",
  str_homestory_N21yongchi_90020601_12_dialog_content = "Tch. I'll forgive you, I guess.",
  str_homestory_N21yongchi_90020601_13_dialog_content = "And, er... Actually, I would love to go in and enjoy the pool.",
  str_homestory_N21yongchi_90020601_14_dialog_content = "Oh? Go on in. It's free.",
  str_homestory_N21yongchi_90020601_15_dialog_content = "I wasn't worried about the price!",
  str_homestory_N21yongchi_90020601_16_dialog_content = "H-Have you forgotten?",
  str_homestory_N21yongchi_90020601_17_dialog_content = "I'm not... Well, I'm not the best swimmer.",
  str_homestory_N21yongchi_90020601_18_dialog_content = "Oh yes. I remember now.",
  str_homestory_N21yongchi_90020601_19_dialog_content = "Why not try with a swim ring?",
  str_homestory_N21yongchi_90020601_20_dialog_content = "Huh. Those are for kids. I don't want one of those!",
  str_homestory_N21yongchi_90020601_21_dialog_content = "Then there's only one option.",
  str_homestory_N21yongchi_90020601_22_dialog_content = "If you don't want to use a swim ring, you're going to have to learn to swim.",
  str_homestory_N21yongchi_90020601_23_dialog_content = "Exactly. That's why I came to speak to you, PlayerName.",
  str_homestory_N21yongchi_90020601_24_dialog_content = "I'm offering a good chance to let you help me, the great extrozoologist beauty, you know.",
  str_homestory_N21yongchi_90020601_25_dialog_content = "Don't miss it!",
  str_homestory_N21yongchi_90020601_26_dialog_content = "But... I need to welcome everyone, keep the changing rooms tidy, and clean the floors and swimming pool.",
  str_homestory_N21yongchi_90020601_27_dialog_content = "I'm afraid I don't have time to teach you, Fia.",
  str_homestory_N21yongchi_90020601_28_dialog_content = "Oh... Y-You're turning me down?",
  str_homestory_N21yongchi_90020601_29_dialog_content = "No, no, how could I do that?",
  str_homestory_N21yongchi_90020601_30_dialog_content = "How about this? I'll get Vice to teach you.",
  str_homestory_N21yongchi_90020601_31_dialog_content = "She's a much better swimmer than I am.",
  str_homestory_N21yongchi_90020601_32_dialog_content = "Hmm. Vice?",
  str_homestory_N21yongchi_90020601_33_dialog_content = "Okay then. I can see you have a lot of work, PlayerName.",
  str_homestory_N21yongchi_90020601_34_dialog_content = "So it wouldn't be polite of me to insist.",
  str_homestory_N21yongchi_90020601_35_dialog_content = "Here are a few small gifts as a thank you.",
  str_homestory_N21yongchi_90020601_36_dialog_content = "Thanks, Fia!",
  str_homestory_N21yongchi_90020601_37_dialog_content = "Yeah! Once I've learned, we can go swimming together.",
  str_homestory_N21yongchi_90020601_38_dialog_content = "Okay. I'll go to find Vice.",
  str_homestory_N21yongchi_90020601_39_dialog_content = "Sure. I'll wait here for you.",
  str_homestory_N21yongchi_90020602_1_dialog_content = "Hmm. That inflatable mat...",
  str_homestory_N21yongchi_90020602_2_dialog_content = "It's very much Fia's style.",
  str_homestory_N21yongchi_90020602_3_dialog_content = "I think I should move the inflatable chair a bit.",
  str_homestory_N21yongchi_90020602_4_dialog_content = "I'll put them away for now in case any of the visitors bump into them.",
  str_homestory_N21yongchi_90020603_1_dialog_content = "Vice? What're you doing in the White Tower? I'm looking for you.",
  str_homestory_N21yongchi_90020603_2_dialog_content = "Hmm! PlayerName! I'm looking for you as well.",
  str_homestory_N21yongchi_90020603_3_dialog_content = "What happened?",
  str_homestory_N21yongchi_90020603_4_dialog_content = "<color=#e8d9bb>Knock, knock!</color>",
  str_homestory_N21yongchi_90020603_5_dialog_content = "It's kind of embarrassing... Seems like the ice cream machine is broken.",
  str_homestory_N21yongchi_90020603_6_dialog_content = "Broken?",
  str_homestory_N21yongchi_90020603_7_dialog_content = "I'm not really sure.",
  str_homestory_N21yongchi_90020603_8_dialog_content = "It just stopped. And I was so enjoying making all my new ice cream flavors.",
  str_homestory_N21yongchi_90020603_9_dialog_content = "Ahh! Come on! How do we save it? Didn't we promise we'd give everyone a great summer?",
  str_homestory_N21yongchi_90020603_10_dialog_content = "It seems like you and the ice cream machine have become close friends.",
  str_homestory_N21yongchi_90020603_11_dialog_content = "Of course! We've been working hard side-by-side for 20 hours now, non-stop.",
  str_homestory_N21yongchi_90020603_12_dialog_content = "20 hours! Vice, you need to take a break.",
  str_homestory_N21yongchi_90020603_13_dialog_content = "And I suspect the problem with the machine might be related to overwork.",
  str_homestory_N21yongchi_90020603_14_dialog_content = "Hmmm. I may have overlooked that possibility.",
  str_homestory_N21yongchi_90020603_15_dialog_content = "Maybe it's my fault it broke... And after you went to so much trouble to get it. Sorry, PlayerName.",
  str_homestory_N21yongchi_90020603_16_dialog_content = "I was planning an absolutely mind-blowing flavor for you to feast on.",
  str_homestory_N21yongchi_90020603_17_dialog_content = "Well, it's the thought that counts.",
  str_homestory_N21yongchi_90020603_18_dialog_content = "Was it doing anything unusual before it stopped?",
  str_homestory_N21yongchi_90020603_19_dialog_content = "Let me think. I think there might have been a flashing red light.",
  str_homestory_N21yongchi_90020603_20_dialog_content = "So maybe it wasn't getting enough power?",
  str_homestory_N21yongchi_90020603_21_dialog_content = "There were two signals on it. A tree and a rock.",
  str_homestory_N21yongchi_90020603_22_dialog_content = "Maybe we could feed it some wood and ore and see what happens?",
  str_homestory_N21yongchi_90020603_23_dialog_content = "Although I don't see why an ice cream machine would run on wood and ore.",
  str_homestory_N21yongchi_90020603_24_dialog_content = "I'll go and get some anyway. We'll see what happens.",
  str_homestory_N21yongchi_90020604_1_dialog_content = "Did you get the wood?",
  str_homestory_N21yongchi_90020604_2_dialog_content = "Sure did. ({1}/{2})",
  str_homestory_N21yongchi_90020604_3_dialog_content = "Thanks! Now go and find some ore.",
  str_homestory_N21yongchi_90020604_4_dialog_content = "Will do.",
  str_homestory_N21yongchi_90020604_5_dialog_content = "Not quite enough.",
  str_homestory_N21yongchi_90020604_6_dialog_content = "Good luck! I'll be right here.",
  str_homestory_N21yongchi_90020605_1_dialog_content = "Have you got the ore as well?",
  str_homestory_N21yongchi_90020605_2_dialog_content = "Yeap. ({1}/{2})",
  str_homestory_N21yongchi_90020605_3_dialog_content = "You're always so fast, PlayerName.",
  str_homestory_N21yongchi_90020605_4_dialog_content = "Let's see if it works.",
  str_homestory_N21yongchi_90020605_5_dialog_content = "Okay, I've put everything in.",
  str_homestory_N21yongchi_90020605_6_dialog_content = "Nothing will change if we don't give it a shot. Here, I'll do it.",
  str_homestory_N21yongchi_90020605_7_dialog_content = "<color=#e8d9bb>Crunch crunch.</color>",
  str_homestory_N21yongchi_90020605_8_dialog_content = "<color=#e8d9bb>Crunch crunch.</color>",
  str_homestory_N21yongchi_90020605_9_dialog_content = "I hope this works.",
  str_homestory_N21yongchi_90020605_10_dialog_content = "All we can do now is pray.",
  str_homestory_N21yongchi_90020605_11_dialog_content = "Crunch crunch.",
  str_homestory_N21yongchi_90020605_12_dialog_content = "Er... Vice...",
  str_homestory_N21yongchi_90020605_13_dialog_content = "I just want to ask... You didn't mistreat the ice cream machine, did you?",
  str_homestory_N21yongchi_90020605_14_dialog_content = "Haha. As if I would do that.",
  str_homestory_N21yongchi_90020605_15_dialog_content = "Crunch crunch.",
  str_homestory_N21yongchi_90020605_16_dialog_content = "Crunch crunch crunch crunch.",
  str_homestory_N21yongchi_90020605_17_dialog_content = "Like feed it weird ingredients, maybe?",
  str_homestory_N21yongchi_90020605_18_dialog_content = "Hmm. I don't think so. Unless shells, bones and an entire fish are weird.",
  str_homestory_N21yongchi_90020605_19_dialog_content = "You did what!?",
  str_homestory_N21yongchi_90020605_20_dialog_content = "And... Well, if the ingredient intake got jammed, I might have given it a good thump.",
  str_homestory_N21yongchi_90020605_21_dialog_content = "But a very accurate thump, I promise!",
  str_homestory_N21yongchi_90020605_22_dialog_content = "Perfectly tailored to the problem. And it didn't do any damage!",
  str_homestory_N21yongchi_90020605_23_dialog_content = "I knew it. You should try being a little more gentle with it.",
  str_homestory_N21yongchi_90020605_24_dialog_content = "Hopefully it's just run out of power. Otherwise I don't know how we'll fix it.",
  str_homestory_N21yongchi_90020605_25_dialog_content = "I-I know. I'll be more careful.",
  str_homestory_N21yongchi_90020605_26_dialog_content = "PlayerName, this is awesome!",
  str_homestory_N21yongchi_90020605_27_dialog_content = "I still don't understand HOW it works. But I'm happy it does!",
  str_homestory_N21yongchi_90020605_28_dialog_content = "Excellent. We got the ice cream machine back up and running.",
  str_homestory_N21yongchi_90020605_29_dialog_content = "Oh, I almost forgot why I came.",
  str_homestory_N21yongchi_90020605_30_dialog_content = "Fia actually wants to learn to swim, and I know you're a good swimmer.",
  str_homestory_N21yongchi_90020605_31_dialog_content = "So maybe you could teach her, when you have time?",
  str_homestory_N21yongchi_90020605_32_dialog_content = "What, is that all?",
  str_homestory_N21yongchi_90020605_33_dialog_content = "Let me grab these and fix the ice-cream machine, and then I'll meet with Fia.",
  str_homestory_N21yongchi_90020605_34_dialog_content = "Tell her to wait for me by the pool. I'll show her some of Illumina's best training methods.",
  str_homestory_N21yongchi_90020605_35_dialog_content = "Fia will get it down this time. That'll be something to celebrate!",
  str_homestory_N21yongchi_90020605_36_dialog_content = "It will be right up.",
  str_homestory_N21yongchi_90020605_37_dialog_content = "Just a little more, come on!",
  str_homestory_N21yongchi_90020606_1_dialog_content = "Puff... I'm exhausted.",
  str_homestory_N21yongchi_90020606_2_dialog_content = "PlayerName, you seem very busy.",
  str_homestory_N21yongchi_90020606_3_dialog_content = "It must be tiring managing such a big place.",
  str_homestory_N21yongchi_90020606_4_dialog_content = "Sure is. I need to look after lots of different things here.",
  str_homestory_N21yongchi_90020606_5_dialog_content = "But I'm happy to have created a place where everyone can enjoy themselves.",
  str_homestory_N21yongchi_90020606_6_dialog_content = "That's true, but you don't have any time to relax and have fun yourself, do you?",
  str_homestory_N21yongchi_90020606_7_dialog_content = "Heh. No, that is true.",
  str_homestory_N21yongchi_90020606_8_dialog_content = "I've been working from dawn to dusk lately.",
  str_homestory_N21yongchi_90020606_9_dialog_content = "Yes. Just as Vice and I thought.",
  str_homestory_N21yongchi_90020606_10_dialog_content = "Which is why we came to help.",
  str_homestory_N21yongchi_90020606_11_dialog_content = "We're going to take over the management of the water park for a while.",
  str_homestory_N21yongchi_90020606_12_dialog_content = "Then you'll be able to enjoy it too.",
  str_homestory_N21yongchi_90020606_13_dialog_content = "Seriously?",
  str_homestory_N21yongchi_90020606_14_dialog_content = "Of course. You deserve it.",
  str_homestory_N21yongchi_90020606_15_dialog_content = "I mean, we can't always be benefiting from all your hard work, can we?",
  str_homestory_N21yongchi_90020606_16_dialog_content = "Amazing. I've been hoping to do this!",
  str_homestory_N21yongchi_90020606_17_dialog_content = "Now I'm going to enjoy myself from dawn to dusk.",
  str_homestory_N21yongchi_90020606_18_dialog_content = "I'm going to swim 300 laps in the pool.",
  str_homestory_N21yongchi_90020606_19_dialog_content = "Then I'm going to stuff myself with ice cream and fall asleep on a lounge chair.",
  str_homestory_N21yongchi_90020606_20_dialog_content = "Great. Go have fun!",
  str_homestory_N21yongchi_90020606_21_dialog_content = "It's your summer too, remember.",
  str_homestory_N21yongchi_90029901_1_dialog_content = "Go and ask Ciel.",
  str_homestory_N21yongchi_90029901_2_dialog_content = "Could you... get me some ore?",
  str_homestory_N21yongchi_90029901_3_dialog_content = "Wait a minute. I need to make some adjustments to Styx.",
  str_homestory_N21yongchi_90029902_1_dialog_content = "Go and ask Rainbow, I'll wait here.",
  str_homestory_N21yongchi_90029902_2_dialog_content = "Did you get the fish?",
  str_homestory_N21yongchi_90029902_3_dialog_content = "This isn't enough water. Could you get some more?",
  str_homestory_N21yongchi_90029903_1_dialog_content = "I thought you were going to see Vice?",
  str_homestory_N21yongchi_90029903_2_dialog_content = "Hurry up and find people to test the new flavors!",
  str_homestory_N21yongchi_90029904_1_dialog_content = "Where has Philyshy gone?",
  str_homestory_N21yongchi_90029905_1_dialog_content = "Rainbow should know.",
  str_homestory_N21yongchi_90029905_2_dialog_content = "Go and ask Ringmaster Jeno.",
  str_homestory_N21yongchi_90029905_3_dialog_content = "I'm waiting for you to prove your resolve.",
  str_homestory_N21yongchi_90029906_1_dialog_content = "Tidy things up, then hurry and ask Vice.",
  str_homestory_N21yongchi_90029906_2_dialog_content = "Collect the wood first.",
  str_homestory_N21yongchi_90029906_3_dialog_content = "Did you collect the ore?",
  str_homestory_N21yongchi_90029906_4_dialog_content = "PlayerName! Are you done with your thing?"
}
return config
